data class Nöqte(val x: Int, val y: Int) {

    operator fun plus(digeri: Nöqte) = Nöqte(x + digeri.x, y + digeri.y)
    operator fun minus(digeri: Nöqte) = Nöqte(x - digeri.x, y - digeri.y)
    operator fun times(k: Int) = Nöqte(x * k, y * k)

    // in operatoru
    operator fun contains(deyer: Int) = deyer == x || deyer == y

    // indeksləmə: p[0], p[1]
    operator fun get(index: Int) = when (index) {
        0 -> x
        1 -> y
        else -> throw IndexOutOfBoundsException()
    }
}

fun main() {
    val a = Nöqte(1, 2)
    val b = Nöqte(3, 4)

    println(a + b)
    println(b - a)
    println(Nöqte(2, 3) * 3)
    println(2 in a)          // contains() çağırılır
    println("x = ${a[0]}")   // get() çağırılır
}

