fun main() {
    // 1) Sadə dəyər uyğunlaşdırması
    val x = 2
    when (x) {
        1 -> println("Bir")
        2, 3 -> println("Kiçik rəqəm: $x")   // bir neçə dəyər vergüllə
        else -> println("Digər")
    }

    // 2) İfadə kimi + aralıq
    val gun = 3
    val tip = when (gun) {
        in 1..5 -> "İş günü"
        6, 7 -> "İstirahət"
        else -> "Yanlış gün"
    }
    println(tip)

    // 3) Tip yoxlaması (is) — smart cast işləyir
    val obyekt: Any = 42
    when (obyekt) {
        is Int -> println("Rəqəm")
        is String -> println("Uzunluq: ${obyekt.length}")  // avtomatik String
        is List<*> -> println("Siyahı, ${obyekt.size} element")
        else -> println("Naməlum tip")
    }

    // 4) Arqumentsiz when — if-else zəncirini əvəz edir
    val temperatur = 5
    val geyim = when {
        temperatur < 0 -> "Qalın palto"
        temperatur in 1..10 -> "1-dən 10-a qədər"
        temperatur in 11..20 -> "Yüngül gödəkçə"
        else -> "Köynək"
    }
    println(geyim)

    // 5) when nəticəsini birbaşa qaytarmaq
    println(olcuAdi(150))
}

