fun main() {
    // break — dövrü tamamilə dayandırır
    for (i in 1..5) {
        if (i == 3) break
        print("$i ")
    }
    println()

    // continue — cari addımı atlayır
    for (i in 1..5) {
        if (i % 2 == 0) continue
        print("$i ")
    }
    println()

    // Etiket — iç-içə dövrlərdən çıxmaq üçün
    xarici@ for (i in 1..3) {
        for (j in 1..3) {
            if (i * j == 2) {
                println("Tapıldı: ($i, $j)")
                break@xarici     // hər iki dövrdən çıxır
            }
        }
    }
}

