// Generik funksiya — T istənilən tip ola bilər
fun <T> ilkini(siyahi: List<T>): T = siyahi.first()

// Generik sinif
class Qutu<T>(private val deyer: T) {
    fun al(): T = deyer
    fun cap() = println("Qutuda: $deyer")
}

fun main() {
