    Qutu(42).cap()
}

// T yalnız Comparable ola bilər — indi > operatoru işləyir
fun <T : Comparable<T>> boyuk(a: T, b: T): T = if (a > b) a else b

// Bir neçə məhdudiyyət — where ilə
fun <T> emalEt(element: T): List<T>
    where T : Comparable<T>, T : Any = listOf(element)

// Nullable olmayan tip tələb etmək
fun <T : Any> tələbEt(deyer: T?): T = deyer ?: error("null ola bilməz")

fun main() {
    println(boyuk(9, 3))
    println(boyuk("Java", "Kotlin"))
    println(listOf(1, 2, 3).sorted())
}

open class Heyvan
class It : Heyvan()

// out — istehsalçı (producer): yalnız T qaytarır
class Menbe<out T>(private val deyer: T) {
    fun al(): T = deyer
    // fun yaz(x: T) { }    ← XƏTA: out tipi parametr ola bilməz
}

// in — istehlakçı (consumer): yalnız T qəbul edir
class Hedef<in T> {
    fun yaz(deyer: T) = println(deyer)
    // fun al(): T          ← XƏTA: in tipi qaytarıla bilməz
}

fun main() {
    val itMenbe: Menbe<It> = Menbe(It())
    val heyvanMenbe: Menbe<Heyvan> = itMenbe      // out sayəsində işləyir

    val heyvanHedef: Hedef<Heyvan> = Hedef()
    val itHedef: Hedef<It> = heyvanHedef          // in sayəsində işləyir

    // MutableList invariantdır:
    // val a: MutableList<Heyvan> = mutableListOf<It>()  ← XƏTA
    // Səbəb: sonra ora Pisik əlavə etmək olardı!

    // List isə kovariantdır (List<out E>) — oxumaq təhlükəsizdir:
    val b: List<Heyvan> = listOf<It>()            // işləyir
}

// reified olmadan: "Cannot check for instance of erased type: T"
inline fun <reified T> List<*>.yalnizTipi(): List<T> =
    filterIsInstance<T>()

inline fun <reified T> tipdirmi(deyer: Any): Boolean = deyer is T

fun main() {
    val qarisiq = listOf(1, "iki", 3, "dörd")

    println(qarisiq.yalnizTipi<String>())
    println(qarisiq.yalnizTipi<Int>())
    println(tipdirmi<String>("Kotlin"))
}

