import kotlinx.coroutines.*

fun main() = runBlocking {
    val is1 = launch {
        try {
            repeat(100) { i ->
                println("İşlənir $i")
                delay(100)          // ləğvetməyə həssas nöqtə
            }
        } catch (e: CancellationException) {
            println("Ləğv olundu")
            throw e                 // MÜTLƏQ yenidən atılmalıdır
        } finally {
            // withContext(NonCancellable) { ... } — təmizlik suspend-dirsə
            println("Təmizlik aparıldı")
        }
    }

    delay(350)
    is1.cancelAndJoin()
}

import kotlinx.coroutines.*

fun main() = runBlocking {
    // 1) try/catch — adi qaydada işləyir
    try {
        coroutineScope {
            launch { throw RuntimeException("xəta!") }
        }
    } catch (e: Exception) {
        println("Tutuldu: ${e.message}")
    }

    // 2) supervisorScope — bir uşağın xətası digərlərini öldürmür
    supervisorScope {
        launch { throw RuntimeException("birinci uğursuz") }
        launch { delay(100); println("ikinci yenə də işlədi") }
    }

    // 3) CoroutineExceptionHandler — launch üçün qlobal tutucu
    val handler = CoroutineExceptionHandler { _, e ->
        println("Handler tutdu: ${e.message}")
    }
    val scope = CoroutineScope(Dispatchers.Default + handler)
    scope.launch { throw RuntimeException("arxa fonda xəta") }

    delay(300)
}

