class BalansXetasi(
    val catismayan: Double,
    val kod: String = "INSUFFICIENT_FUNDS"
) : Exception("Balans kifayət etmir. Çatışmayan: $catismayan")

fun mexaric(balans: Double, mebleg: Double): Double {
    if (mebleg > balans) throw BalansXetasi(mebleg - balans)
    return balans - mebleg
}

