sealed interface Cavab<out T> {
    data class Ugur<T>(val data: T) : Cavab<T>
    sealed interface Xeta : Cavab<Nothing> {
        data object SebekeYoxdur : Xeta
        data class Server(val kod: Int) : Xeta
        data class Validasiya(val sahe: String) : Xeta
    }
}

fun idareEt(c: Cavab<String>): String = when (c) {
    is Cavab.Ugur -> "Data: ${c.data}"
    Cavab.Xeta.SebekeYoxdur -> "İnternet bağlantısı yoxdur"
    is Cavab.Xeta.Server -> "Server xətası: ${c.kod}"
    is Cavab.Xeta.Validasiya -> "Sahə yanlışdır: ${c.sahe}"
}

