import kotlin.properties.Delegates

class Istifadeci {
    // observable — hər dəyişiklikdən SONRA xəbər verir
    var ad: String by Delegates.observable("Aysel") { _, kohne, yeni ->
        println("Dəyişdi: $kohne -> $yeni")
    }

    // vetoable — dəyişikliyi RƏDD edə bilər
    var etibarliAd: String by Delegates.vetoable("Aysel") { _, _, yeni ->
        if (yeni.isBlank()) {
            println("Rədd edildi (boş ola bilməz)")
            false          // dəyişiklik baş vermir
        } else true
    }

    // notNull — lateinit-in primitiv tiplər üçün qarşılığı
    var yas: Int by Delegates.notNull()
}

fun main() {
    val u = Istifadeci()
    u.ad = "Leyla"
    println("Ad: ${u.ad}")

    u.etibarliAd = "Leyla"
    u.etibarliAd = ""
    println("Ad: ${u.etibarliAd}")
}

