import kotlin.reflect.KProperty

class LoglayanDelegat<T>(private var deyer: T) {

    operator fun getValue(sahib: Any?, xasse: KProperty<*>): T {
        println("${xasse.name} oxunur")
        return deyer
    }

    operator fun setValue(sahib: Any?, xasse: KProperty<*>, yeni: T) {
        println("${xasse.name} yazılır: $yeni")
        deyer = yeni
    }
}

class Profil {
    var ad: String by LoglayanDelegat("Aysel")
}

