// UI vəziyyəti — sealed interface ilə modelləşdirilir
sealed interface EkranVeziyyeti {
    data object Yuklenir : EkranVeziyyeti
    data class Ugurlu(val istifadeciler: List<Istifadeci>) : EkranVeziyyeti
    data class Xeta(val mesaj: String) : EkranVeziyyeti
}

class IstifadeciViewModel(
    private val repo: IstifadeciRepo
) : ViewModel() {

    private val _veziyyet = MutableStateFlow<EkranVeziyyeti>(EkranVeziyyeti.Yuklenir)
    val veziyyet: StateFlow<EkranVeziyyeti> = _veziyyet.asStateFlow()

    init { yukle() }

    fun yukle() {
        viewModelScope.launch {          // ViewModel məhv olanda avtomatik ləğv olunur
            _veziyyet.value = EkranVeziyyeti.Yuklenir
            _veziyyet.value = runCatching { repo.hamisiniGetir() }
                .fold(
                    onSuccess = { EkranVeziyyeti.Ugurlu(it) },
                    onFailure = { EkranVeziyyeti.Xeta(it.message ?: "Naməlum xəta") }
                )
        }
    }
}

@Composable
fun IstifadeciEkrani(vm: IstifadeciViewModel) {
    val veziyyet by vm.veziyyet.collectAsStateWithLifecycle()

    when (val v = veziyyet) {        // exhaustive — heç bir hal unudulmur
        EkranVeziyyeti.Yuklenir -> CircularProgressIndicator()
        is EkranVeziyyeti.Ugurlu -> LazyColumn {
            items(v.istifadeciler) { istifadeci ->
                ListItem(headlineContent = { Text(istifadeci.ad) })
            }
        }
        is EkranVeziyyeti.Xeta -> Column {
            Text(v.mesaj)
            Button(onClick = vm::yukle) { Text("Yenidən cəhd et") }
        }
    }
}

